import json,subprocess,os
p=json.load(open('plan.json'))
bad=[]
for i,s in enumerate(p['segments']):
    f='segments/%04d.mp4'%i
    exp=s['t1']-s['t0']
    if not os.path.exists(f):
        bad.append((i,f,exp,0.0,'MISSING')); continue
    try:
        out=subprocess.run(['ffprobe','-v','error','-show_entries','format=duration','-of','csv=p=0',f],capture_output=True,text=True,timeout=60).stdout.strip()
        d=float(out)
    except Exception as e:
        bad.append((i,f,exp,0.0,'PROBE '+str(e))); continue
    if d < exp-0.35 or d > exp+0.9:
        bad.append((i,f,exp,round(d,2),'SHORT' if d<exp else 'LONG'))
print('checked',len(p['segments']),'bad',len(bad))
for b in bad: print(b)
